#!/usr/bin/env bash
# Run from any directory; all generated files remain inside this repository.
set -euo pipefail

repo_root=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd -P)
cd -- "$repo_root"
extras=test
build_java=false
for option in "$@"; do
  case "$option" in
    --ml) extras+=,ml ;;
    --analysis) extras+=,analysis ;;
    --tune) extras+=,tune ;;
    --java) build_java=true ;;
    -h|--help)
      printf '%s\n' 'Usage: ./setup.sh [--ml] [--analysis] [--tune] [--java]' \
        'Creates/reuses .venv and installs the package plus test dependencies.' \
        '--ml: install ML extras; --analysis: install plotting; --tune: install Ray Tune; --java: build graph extractor.' \
        'Requires Python 3.10+ (override with PYTHON); --java requires Java 17 and Maven.' \
        'After setup, run: source .local/env.sh'
      exit 0 ;;
    *) printf 'Unknown option: %s\n' "$option" >&2; exit 2 ;;
  esac
done

python_bin=${PYTHON:-python3}
"$python_bin" - <<'PY'
import sys
from pathlib import Path
if sys.version_info < (3, 10):
    raise SystemExit('Python 3.10+ is required.')
root = Path.cwd().resolve()
for name in ('.venv', '.local', '.local/env.sh', '.local/tmp', '.local/cache',
             '.local/config', '.local/pycache', '.local/dgl',
             '.local/m2', '.local/torch', '.local/huggingface', 'src/qpp/java/qpe',
             'src/qpp/java/qpe/target', 'src/qpp/java/qpe/dependency-reduced-pom.xml'):
    if not (root / name).resolve().is_relative_to(root):
        raise SystemExit(f'Setup path escapes repository: {name}')
PY

if "$build_java"; then
  command -v java >/dev/null || { printf 'Install Java 17 first.\n' >&2; exit 1; }
  command -v mvn >/dev/null || { printf 'Install Maven first.\n' >&2; exit 1; }
fi

mkdir -p .local/{tmp,cache,config,pycache,dgl,m2,torch,huggingface}
export TMPDIR="$repo_root/.local/tmp" XDG_CACHE_HOME="$repo_root/.local/cache"
export XDG_CONFIG_HOME="$repo_root/.local/config" PYTHONPYCACHEPREFIX="$repo_root/.local/pycache"
export PIP_CACHE_DIR="$repo_root/.local/cache/pip" DGLDEFAULTDIR="$repo_root/.local/dgl"
export TORCH_HOME="$repo_root/.local/torch"
export HF_HOME="$repo_root/.local/huggingface"

if [[ ! -f .venv/pyvenv.cfg ]]; then
  "$python_bin" -m venv .venv
fi
.venv/bin/python -m pip install -e ".[${extras}]"

if "$build_java"; then
  MAVEN_OPTS="${MAVEN_OPTS:-} -Djava.io.tmpdir=$TMPDIR" \
    mvn -f src/qpp/java/qpe/pom.xml -Dmaven.repo.local="$repo_root/.local/m2" package
fi

{
  printf '# Generated by setup.sh; source this file from Bash.\n'
  for variable in TMPDIR XDG_CACHE_HOME XDG_CONFIG_HOME PYTHONPYCACHEPREFIX \
    PIP_CACHE_DIR DGLDEFAULTDIR TORCH_HOME HF_HOME; do
    printf 'export %s=%q\n' "$variable" "${!variable}"
  done
  printf 'source %q\n' "$repo_root/.venv/bin/activate"
  printf 'cd -- %q\n' "$repo_root"
} > .local/env.sh
printf '\nSetup complete. Run: source %q\n' "$repo_root/.local/env.sh"
